  "Bring your own endpoint: nothing is ever sent to any AI service unless you ask, and only to the endpoint you configure here. Replies are inserted, never executed.": {
    "en": "Bring your own endpoint: nothing is ever sent to any AI service unless you ask, and only to the endpoint you configure here. Replies are inserted, never executed.",
    "de": "Eigener Endpunkt: Es wird nie etwas an einen KI-Dienst gesendet, außer Sie fordern es an, und dann nur an den hier konfigurierten Endpunkt. Antworten werden eingefügt, niemals ausgeführt.",
    "es": "Use su propio endpoint: nunca se envía nada a ningún servicio de IA a menos que lo pida, y solo al endpoint que configure aquí. Las respuestas se insertan, nunca se ejecutan.",
    "fr": "Utilisez votre propre point de terminaison : rien n’est jamais envoyé à un service d’IA sans votre demande, et uniquement au point de terminaison configuré ici. Les réponses sont insérées, jamais exécutées.",
    "it": "Usa il tuo endpoint: nulla viene mai inviato a un servizio AI se non lo richiedi, e solo all'endpoint configurato qui. Le risposte vengono inserite, mai eseguite.",
    "ja": "エンドポイントは自分で用意: 依頼しない限り AI サービスには何も送信されず、送信先もここで設定したエンドポイントだけです。応答は挿入されるだけで、実行されることはありません。",
    "pt": "Use o seu próprio endpoint: nada é enviado para nenhum serviço de IA a menos que o peça, e apenas para o endpoint que configurar aqui. As respostas são inseridas, nunca executadas.",
    "ru": "Используйте собственную конечную точку: ничего не отправляется ни в какой ИИ-сервис, пока вы не попросите, и только на настроенную здесь конечную точку. Ответы вставляются, но никогда не выполняются.",
    "zh": "自带端点：除非你主动询问，否则不会向任何 AI 服务发送任何内容，且仅发送到你在此配置的端点。回复只会被插入，绝不会被执行。"
  },
