  "Color keywords in terminal output to speed up log triage. Rules apply to every terminal and persist across restarts.": {
    "en": "Color keywords in terminal output to speed up log triage. Rules apply to every terminal and persist across restarts.",
    "de": "Schlüsselwörter in der Terminalausgabe einfärben, um die Log-Analyse zu beschleunigen. Regeln gelten für jedes Terminal und bleiben über Neustarts hinweg erhalten.",
    "es": "Resalte palabras clave en la salida del terminal para agilizar el análisis de registros. Las reglas se aplican a todos los terminales y se conservan tras reiniciar.",
    "fr": "Colorez des mots-clés dans la sortie du terminal pour accélérer l’analyse des journaux. Les règles s’appliquent à tous les terminaux et sont conservées après redémarrage.",
    "it": "Colora le parole chiave nell'output del terminale per velocizzare l'analisi dei log. Le regole si applicano a ogni terminale e restano attive dopo il riavvio.",
    "ja": "ターミナル出力のキーワードを色分けして、ログの切り分けを素早く行えます。ルールはすべてのターミナルに適用され、再起動後も保持されます。",
    "pt": "Colorir palavras-chave na saída do terminal para acelerar a triagem de registos. As regras aplicam-se a todos os terminais e persistem entre reinícios.",
    "ru": "Выделять ключевые слова в выводе терминала цветом для быстрого разбора журналов. Правила применяются ко всем терминалам и сохраняются после перезапуска.",
    "zh": "为终端输出中的关键字着色，以加快日志排查。规则适用于所有终端，并在重启后保留。"
  },
