  "Create an SSH profile before starting a tunnel. Local, RDP, VNC, Telnet and serial profiles cannot own OpenSSH forwarding processes.": {
    "en": "Create an SSH profile before starting a tunnel. Local, RDP, VNC, Telnet and serial profiles cannot own OpenSSH forwarding processes.",
    "de": "Erstellen Sie ein SSH-Profil, bevor Sie einen Tunnel starten. Lokale, RDP-, VNC-, Telnet- und serielle Profile können keine OpenSSH-Weiterleitungsprozesse besitzen.",
    "es": "Cree un perfil SSH antes de iniciar un túnel. Los perfiles locales, RDP, VNC, Telnet y serie no pueden gestionar procesos de reenvío de OpenSSH.",
    "fr": "Créez un profil SSH avant de démarrer un tunnel. Les profils locaux, RDP, VNC, Telnet et série ne peuvent pas gérer de processus de redirection OpenSSH.",
    "it": "Creare un profilo SSH prima di avviare un tunnel. I profili locali, RDP, VNC, Telnet e seriali non possono possedere processi di inoltro OpenSSH.",
    "ja": "トンネルを開始する前に SSH プロファイルを作成してください。ローカル、RDP、VNC、Telnet、シリアルの各プロファイルは OpenSSH のフォワーディングプロセスを持てません。",
    "pt": "Crie um perfil SSH antes de iniciar um túnel. Perfis locais, RDP, VNC, Telnet e série não podem ser donos de processos de reencaminhamento OpenSSH.",
    "ru": "Создайте профиль SSH перед запуском туннеля. Локальные профили, а также RDP, VNC, Telnet и профили последовательного порта не могут управлять процессами перенаправления OpenSSH.",
    "zh": "启动隧道前请先创建 SSH 配置文件。本地、RDP、VNC、Telnet 和串口配置文件无法拥有 OpenSSH 转发进程。"
  },
