  "Macro recording may capture secrets typed into this terminal. Do not record passwords, tokens, recovery codes, or private customer data.": {
    "en": "Macro recording may capture secrets typed into this terminal. Do not record passwords, tokens, recovery codes, or private customer data.",
    "de": "Bei der Makroaufzeichnung können in dieses Terminal eingegebene Geheimnisse erfasst werden. Zeichnen Sie keine Passwörter, Tokens, Wiederherstellungscodes oder privaten Kundendaten auf.",
    "es": "La grabación de macros puede capturar secretos escritos en este terminal. No grabe contraseñas, tokens, códigos de recuperación ni datos privados de clientes.",
    "fr": "L’enregistrement de macro peut capturer des secrets tapés dans ce terminal. N’enregistrez pas de mots de passe, jetons, codes de récupération ou données privées de clients.",
    "it": "La registrazione di macro può catturare segreti digitati in questo terminale. Non registrare password, token, codici di recupero o dati privati dei clienti.",
    "ja": "マクロの記録では、このターミナルに入力した機密情報も記録される場合があります。パスワード、トークン、リカバリーコード、顧客の個人データは記録しないでください。",
    "pt": "A gravação de macros pode capturar segredos escritos neste terminal. Não grave palavras-passe, tokens, códigos de recuperação nem dados privados de clientes.",
    "ru": "При записи макроса могут быть захвачены секреты, введённые в этот терминал. Не записывайте пароли, токены, коды восстановления и конфиденциальные данные клиентов.",
    "zh": "宏录制可能会捕获在此终端中输入的机密信息。请勿录制密码、令牌、恢复代码或客户隐私数据。"
  },
