  "Managed tunnels use OpenSSH BatchMode. Configure key or SSH-agent authentication; interactive password and MFA prompts are not available for background tunnels.": {
    "en": "Managed tunnels use OpenSSH BatchMode. Configure key or SSH-agent authentication; interactive password and MFA prompts are not available for background tunnels.",
    "de": "Verwaltete Tunnel verwenden OpenSSH BatchMode. Konfigurieren Sie Schlüssel- oder SSH-Agent-Authentifizierung; interaktive Passwort- und MFA-Abfragen sind für Hintergrundtunnel nicht verfügbar.",
    "es": "Los túneles gestionados usan OpenSSH BatchMode. Configure la autenticación por clave o por SSH-agent; las solicitudes interactivas de contraseña y MFA no están disponibles para los túneles en segundo plano.",
    "fr": "Les tunnels gérés utilisent le BatchMode d’OpenSSH. Configurez une authentification par clé ou par agent SSH ; les invites interactives de mot de passe et de MFA ne sont pas disponibles pour les tunnels en arrière-plan.",
    "it": "I tunnel gestiti usano OpenSSH BatchMode. Configura l'autenticazione con chiave o SSH-agent; password interattive e richieste MFA non sono disponibili per i tunnel in background.",
    "ja": "管理対象のトンネルは OpenSSH の BatchMode を使用します。鍵認証または SSH-agent 認証を設定してください。バックグラウンドのトンネルでは、対話的なパスワード入力や MFA プロンプトは使用できません。",
    "pt": "Os túneis geridos usam o OpenSSH BatchMode. Configure a autenticação por chave ou por SSH-agent; as palavras-passe interativas e pedidos MFA não estão disponíveis para túneis em segundo plano.",
    "ru": "Управляемые туннели используют OpenSSH BatchMode. Настройте аутентификацию по ключу или через SSH-агент; интерактивный ввод пароля и запросы MFA для фоновых туннелей недоступны.",
    "zh": "托管隧道使用 OpenSSH BatchMode。请配置密钥或 SSH-agent 认证；后台隧道无法使用交互式密码和 MFA 提示。"
  },
