  "Plain FTP is not encrypted. Credentials and file contents can be observed on the network. Use FTPS unless this is a trusted legacy target.": {
    "en": "Plain FTP is not encrypted. Credentials and file contents can be observed on the network. Use FTPS unless this is a trusted legacy target.",
    "de": "Einfaches FTP ist nicht verschlüsselt. Anmeldedaten und Dateiinhalte können im Netzwerk mitgelesen werden. Verwenden Sie FTPS, sofern es sich nicht um ein vertrauenswürdiges Altsystem handelt.",
    "es": "El FTP simple no está cifrado. Las credenciales y el contenido de los archivos pueden observarse en la red. Use FTPS salvo que se trate de un sistema heredado de confianza.",
    "fr": "FTP simple n’est pas chiffré. Les identifiants et le contenu des fichiers peuvent être observés sur le réseau. Utilisez FTPS, sauf s’il s’agit d’une ancienne cible de confiance.",
    "it": "FTP semplice non è cifrato. Credenziali e contenuto dei file possono essere osservati in rete. Usa FTPS a meno che non si tratti di una destinazione legacy attendibile.",
    "ja": "プレーン FTP は暗号化されません。認証情報やファイルの内容がネットワーク上で傍受される可能性があります。信頼できるレガシーな接続先でない限り、FTPS を使用してください。",
    "pt": "O FTP simples não é encriptado. As credenciais e o conteúdo dos ficheiros podem ser observados na rede. Use FTPS, exceto se for um destino antigo de confiança.",
    "ru": "Обычный FTP не шифруется. Учётные данные и содержимое файлов можно перехватить в сети. Используйте FTPS, если это не доверенная устаревшая система.",
    "zh": "普通 FTP 不加密。网络上的其他人可能看到凭据和文件内容。除非连接的是可信的旧系统，否则请使用 FTPS。"
  },
  "Plain text matches literally; wrap a pattern in /slashes/ for a regular expression. Highlighting applies to normal terminal output, not full-screen apps like vim or htop.": {
    "en": "Plain text matches literally; wrap a pattern in /slashes/ for a regular expression. Highlighting applies to normal terminal output, not full-screen apps like vim or htop.",
    "de": "Klartext wird wörtlich abgeglichen; setzen Sie ein Muster für einen regulären Ausdruck in /Schrägstriche/. Die Hervorhebung gilt für normale Terminalausgabe, nicht für Vollbild-Apps wie vim oder htop.",
    "es": "El texto sin formato coincide literalmente; encierre un patrón entre /barras/ para usar una expresión regular. El resaltado se aplica a la salida normal del terminal, no a aplicaciones de pantalla completa como vim o htop.",
    "fr": "Le texte simple est recherché tel quel ; entourez un motif de /barres obliques/ pour une expression régulière. La coloration s’applique à la sortie normale du terminal, pas aux applications plein écran comme vim ou htop.",
    "it": "Il testo semplice corrisponde letteralmente; racchiudi un pattern tra /barre/ per un'espressione regolare. L'evidenziazione si applica al normale output del terminale, non alle app a schermo intero come vim o htop.",
    "ja": "プレーンテキストはそのまま一致します。正規表現を使うにはパターンを /slashes/ のようにスラッシュで囲みます。強調表示は通常のターミナル出力に適用され、vim や htop などの全画面アプリには適用されません。",
    "pt": "O texto simples corresponde literalmente; envolva um padrão em /barras/ para uma expressão regular. O realce aplica-se à saída normal do terminal, não a aplicações de ecrã inteiro como o vim ou o htop.",
    "ru": "Обычный текст ищется буквально; для регулярного выражения заключите шаблон в /косые черты/. Подсветка применяется к обычному выводу терминала, а не к полноэкранным приложениям вроде vim или htop.",
    "zh": "纯文本按字面匹配；用 /斜杠/ 包裹模式即可使用正则表达式。高亮适用于普通终端输出，不适用于 vim 或 htop 等全屏应用。"
  },
