  "Terminal logs may capture secrets, commands, hostnames, customer data, and remote output. Choose the log file carefully and stop logging when finished.": {
    "en": "Terminal logs may capture secrets, commands, hostnames, customer data, and remote output. Choose the log file carefully and stop logging when finished.",
    "de": "Terminalprotokolle können Geheimnisse, Befehle, Hostnamen, Kundendaten und Remote-Ausgaben erfassen. Wählen Sie die Protokolldatei sorgfältig aus und beenden Sie die Protokollierung, wenn Sie fertig sind.",
    "es": "Los registros del terminal pueden capturar secretos, comandos, nombres de host, datos de clientes y salida remota. Elija con cuidado el archivo de registro y detenga el registro al terminar.",
    "fr": "Les journaux du terminal peuvent capturer des secrets, des commandes, des noms d’hôte, des données client et la sortie distante. Choisissez le fichier journal avec soin et arrêtez la journalisation une fois terminé.",
    "it": "I log del terminale possono catturare segreti, comandi, nomi host, dati dei clienti e output remoto. Scegli con attenzione il file di log e interrompi il log al termine.",
    "ja": "ターミナルログには機密情報、コマンド、ホスト名、顧客データ、リモートの出力が記録される可能性があります。ログファイルは慎重に選択し、終わったらログ記録を停止してください。",
    "pt": "Os registos do terminal podem capturar segredos, comandos, nomes de host, dados de clientes e saída remota. Escolha o ficheiro de registo com cuidado e pare o registo quando terminar.",
    "ru": "Журналы терминала могут содержать секреты, команды, имена хостов, данные клиентов и удалённый вывод. Тщательно выбирайте файл журнала и останавливайте запись по завершении.",
    "zh": "终端日志可能会捕获机密、命令、主机名、客户数据和远程输出。请谨慎选择日志文件，完成后停止记录。"
  },
