  "This replaces the AppImage on disk with the saved previous version. Your current sessions keep running until you close the application.": {
    "en": "This replaces the AppImage on disk with the saved previous version. Your current sessions keep running until you close the application.",
    "de": "Dies ersetzt das AppImage auf dem Datenträger durch die gespeicherte vorherige Version. Ihre aktuellen Sitzungen laufen weiter, bis Sie die Anwendung schließen.",
    "es": "Esto reemplaza la AppImage del disco por la versión anterior guardada. Sus sesiones actuales siguen en ejecución hasta que cierre la aplicación.",
    "fr": "Cela remplace l’AppImage sur le disque par la version précédente enregistrée. Vos sessions en cours continuent jusqu’à la fermeture de l’application.",
    "it": "L'AppImage su disco viene sostituita con la versione precedente salvata. Le sessioni correnti continuano finché non chiudi l'applicazione.",
    "ja": "ディスク上の AppImage を保存済みの以前のバージョンに置き換えます。現在のセッションはアプリケーションを閉じるまで実行され続けます。",
    "pt": "Isto substitui o AppImage no disco pela versão anterior guardada. As suas sessões atuais continuam em execução até fechar a aplicação.",
    "ru": "AppImage на диске будет заменён сохранённой предыдущей версией. Текущие сеансы продолжат работать, пока вы не закроете приложение.",
    "zh": "这将用已保存的上一个版本替换磁盘上的 AppImage。当前会话将继续运行，直到你关闭应用程序。"
  },
  "This replaces the current profiles and workspace settings. Saved credentials stay in the local keyring.": {
    "en": "This replaces the current profiles and workspace settings. Saved credentials stay in the local keyring.",
    "de": "Dies ersetzt die aktuellen Profile und Arbeitsbereichseinstellungen. Gespeicherte Anmeldedaten bleiben im lokalen Schlüsselbund.",
    "es": "Esto reemplaza los perfiles actuales y la configuración del espacio de trabajo. Las credenciales guardadas permanecen en el llavero local.",
    "fr": "Cela remplace les profils actuels et les paramètres de l’espace de travail. Les identifiants enregistrés restent dans le trousseau local.",
    "it": "Vengono sostituiti i profili e le impostazioni dell'area di lavoro correnti. Le credenziali salvate restano nel portachiavi locale.",
    "ja": "現在のプロファイルとワークスペースの設定を置き換えます。保存された認証情報はローカルのキーリングに残ります。",
    "pt": "Isto substitui os perfis atuais e as definições da área de trabalho. As credenciais guardadas permanecem no porta-chaves local.",
    "ru": "Текущие профили и настройки рабочего пространства будут заменены. Сохранённые учётные данные остаются в локальной связке ключей.",
    "zh": "这将替换当前的配置文件和工作区设置。已保存的凭据仍保留在本地密钥环中。"
  },
