  "Type in a terminal first — history fills as you work (memory only, never saved to disk).": {
    "en": "Type in a terminal first — history fills as you work (memory only, never saved to disk).",
    "de": "Tippen Sie zuerst in einem Terminal – der Verlauf füllt sich während der Arbeit (nur im Arbeitsspeicher, nie auf der Festplatte gespeichert).",
    "es": "Escriba primero en un terminal: el historial se llena mientras trabaja (solo en memoria, nunca se guarda en disco).",
    "fr": "Tapez d’abord dans un terminal — l’historique se remplit au fil du travail (en mémoire uniquement, jamais enregistré sur le disque).",
    "it": "Digita prima in un terminale — la cronologia si riempie mentre lavori (solo in memoria, mai salvata su disco).",
    "ja": "まずターミナルで入力してください。作業に応じて履歴が蓄積されます（メモリ内のみ、ディスクには保存されません）。",
    "pt": "Escreva primeiro num terminal — o histórico é preenchido à medida que trabalha (apenas em memória, nunca guardado no disco).",
    "ru": "Сначала введите что-нибудь в терминале — история пополняется по мере работы (только в памяти, никогда не сохраняется на диск).",
    "zh": "请先在终端中输入命令 — 历史会随工作逐步积累（仅保存在内存中，绝不写入磁盘）。"
  },
  "Typing help, safety checks and OS awareness for every terminal session.": {
    "en": "Typing help, safety checks and OS awareness for every terminal session.",
    "de": "Tipphilfe, Sicherheitsprüfungen und Betriebssystemerkennung für jede Terminalsitzung.",
    "es": "Ayuda de escritura, comprobaciones de seguridad y detección del sistema operativo para cada sesión de terminal.",
    "fr": "Aide à la saisie, contrôles de sécurité et détection de l’OS pour chaque session de terminal.",
    "it": "Aiuto alla digitazione, controlli di sicurezza e riconoscimento del sistema operativo per ogni sessione del terminale.",
    "ja": "すべてのターミナルセッションで入力支援、安全チェック、OS 判別を提供します。",
    "pt": "Ajuda à escrita, verificações de segurança e reconhecimento do SO para todas as sessões de terminal.",
    "ru": "Помощь при вводе, проверки безопасности и учёт ОС для каждого сеанса терминала.",
    "zh": "为每个终端会话提供输入帮助、安全检查和操作系统识别。"
  },
