  "Updates install only after the published manifest and updater metadata pass OpenPGP verification with the bundled Aux Command signing key.": {
    "en": "Updates install only after the published manifest and updater metadata pass OpenPGP verification with the bundled Aux Command signing key.",
    "de": "Updates werden erst installiert, nachdem das veröffentlichte Manifest und die Updater-Metadaten die OpenPGP-Prüfung mit dem mitgelieferten Aux Command-Signaturschlüssel bestanden haben.",
    "es": "Las actualizaciones solo se instalan después de que el manifiesto publicado y los metadatos del actualizador superen la verificación OpenPGP con la clave de firma de Aux Command incluida.",
    "fr": "Les mises à jour ne s’installent qu’après la vérification OpenPGP du manifeste publié et des métadonnées de mise à jour avec la clé de signature d’Aux Command intégrée.",
    "it": "Gli aggiornamenti vengono installati solo dopo che il manifest pubblicato e i metadati dell'updater superano la verifica OpenPGP con la chiave di firma di Aux Command inclusa.",
    "ja": "更新は、公開されたマニフェストとアップデーターのメタデータが、同梱の Aux Command 署名鍵による OpenPGP 検証に合格した場合にのみインストールされます。",
    "pt": "As atualizações só são instaladas depois de o manifesto publicado e os metadados do atualizador passarem a verificação OpenPGP com a chave de assinatura do Aux Command incluída.",
    "ru": "Обновления устанавливаются только после того, как опубликованный манифест и метаданные средства обновления пройдут проверку OpenPGP встроенным ключом подписи Aux Command.",
    "zh": "只有在已发布的清单和更新程序元数据通过内置 Aux Command 签名密钥的 OpenPGP 验证后，才会安装更新。"
  },
