  "Use unique Ctrl+Shift+letter shortcuts. C and V stay reserved for terminal copy/paste. Ctrl+Tab switches tabs.": {
    "en": "Use unique Ctrl+Shift+letter shortcuts. C and V stay reserved for terminal copy/paste. Ctrl+Tab switches tabs.",
    "de": "Verwenden Sie eindeutige Ctrl+Shift+letter-Tastenkombinationen. C und V bleiben für Kopieren/Einfügen im Terminal reserviert. Ctrl+Tab wechselt Tabs.",
    "es": "Use atajos Ctrl+Shift+letra únicos. C y V quedan reservadas para copiar y pegar en el terminal. Ctrl+Tab cambia de pestaña.",
    "fr": "Utilisez des raccourcis Ctrl+Shift+lettre distincts. C et V restent réservés au copier-coller. Ctrl+Tab change d’onglet.",
    "it": "Usa combinazioni Ctrl+Shift+lettera univoche. C e V restano riservati a copia e incolla. Ctrl+Tab cambia scheda.",
    "ja": "Ctrl+Shift+英字のショートカットは重複しないよう設定してください。C と V はターミナルのコピー/貼り付け用に予約されています。Ctrl+Tab でタブを切り替えます。",
    "pt": "Use atalhos únicos Ctrl+Shift+letra. C e V ficam reservados para copiar e colar. Ctrl+Tab muda de separador.",
    "ru": "Используйте уникальные сочетания Ctrl+Shift+буква. C и V зарезервированы для копирования и вставки в терминале. Ctrl+Tab переключает вкладки.",
    "zh": "使用不重复的 Ctrl+Shift+字母快捷键。C 和 V 保留用于复制和粘贴。Ctrl+Tab 切换标签页。"
  },
