  "Bulk edits preserve credentials. Duplicate matches are suggestions; nothing is merged or deleted automatically. Use / in group names for nested folders.": {
    "en": "Bulk edits preserve credentials. Duplicate matches are suggestions; nothing is merged or deleted automatically. Use / in group names for nested folders.",
    "de": "Sammelbearbeitungen erhalten die Anmeldedaten. Duplikat-Treffer sind nur Vorschläge; nichts wird automatisch zusammengeführt oder gelöscht. Verwenden Sie / in Gruppennamen für verschachtelte Ordner.",
    "es": "Las ediciones masivas conservan las credenciales. Las coincidencias duplicadas son sugerencias; no se combina ni elimina nada automáticamente. Use / en los nombres de grupo para carpetas anidadas.",
    "fr": "Les modifications groupées conservent les identifiants. Les doublons détectés ne sont que des suggestions ; rien n’est fusionné ni supprimé automatiquement. Utilisez / dans les noms de groupe pour créer des dossiers imbriqués.",
    "it": "Le modifiche in blocco mantengono le credenziali. Le corrispondenze duplicate sono solo suggerimenti; nulla viene unito o eliminato automaticamente. Usa / nei nomi dei gruppi per le cartelle annidate.",
    "ja": "一括編集では認証情報は保持されます。重複の一致は候補にすぎず、自動的に統合や削除が行われることはありません。フォルダーを入れ子にするにはグループ名に / を使用します。",
    "pt": "As edições em massa preservam as credenciais. As correspondências duplicadas são sugestões; nada é combinado nem eliminado automaticamente. Use / nos nomes de grupos para pastas aninhadas.",
    "ru": "Массовые изменения сохраняют учётные данные. Совпадения-дубликаты — лишь подсказки; ничего не объединяется и не удаляется автоматически. Используйте / в именах групп для вложенных папок.",
    "zh": "批量编辑会保留凭据。重复匹配仅为建议；不会自动合并或删除任何内容。在分组名称中使用 / 可创建嵌套文件夹。"
  },
