  "Existing authenticated sessions are used. Credentials are not copied into task templates. Output stays in this session; terminal logging, if enabled separately, still applies.": {
    "en": "Existing authenticated sessions are used. Credentials are not copied into task templates. Output stays in this session; terminal logging, if enabled separately, still applies.",
    "de": "Vorhandene authentifizierte Sitzungen werden verwendet. Anmeldedaten werden nicht in Aufgabenvorlagen kopiert. Die Ausgabe bleibt in dieser Sitzung; eine separat aktivierte Terminalprotokollierung gilt weiterhin.",
    "es": "Se usan las sesiones autenticadas existentes. Las credenciales no se copian en las plantillas de tareas. La salida permanece en esta sesión; el registro del terminal, si se activa por separado, sigue aplicándose.",
    "fr": "Les sessions déjà authentifiées sont utilisées. Les identifiants ne sont pas copiés dans les modèles de tâches. La sortie reste dans cette session ; la journalisation du terminal, si elle est activée séparément, s’applique toujours.",
    "it": "Vengono usate le sessioni già autenticate. Le credenziali non vengono copiate nei modelli di attività. L'output resta in questa sessione; il log del terminale, se attivato separatamente, resta valido.",
    "ja": "認証済みの既存セッションを使用します。認証情報がタスクテンプレートにコピーされることはありません。出力はこのセッション内に留まります。ターミナルのログ記録を別途有効にしている場合は、そちらも適用されます。",
    "pt": "São usadas as sessões autenticadas existentes. As credenciais não são copiadas para os modelos de tarefas. A saída permanece nesta sessão; o registo do terminal, se ativado à parte, continua a aplicar-se.",
    "ru": "Используются существующие аутентифицированные сеансы. Учётные данные не копируются в шаблоны задач. Вывод остаётся в этом сеансе; журнал терминала, если он включён отдельно, по-прежнему ведётся.",
    "zh": "将使用现有的已认证会话。凭据不会复制到任务模板中。输出保留在此会话中；如果单独启用了终端日志记录，它仍然有效。"
  },
