  "Observed process events and detected errors. Unreported DNS, network and authentication steps are not inferred as successful.": {
    "en": "Observed process events and detected errors. Unreported DNS, network and authentication steps are not inferred as successful.",
    "de": "Beobachtete Prozessereignisse und erkannte Fehler. Nicht gemeldete DNS-, Netzwerk- und Authentifizierungsschritte werden nicht als erfolgreich angenommen.",
    "es": "Eventos de proceso observados y errores detectados. Los pasos de DNS, red y autenticación no notificados no se dan por correctos.",
    "fr": "Événements de processus observés et erreurs détectées. Les étapes DNS, réseau et d’authentification non signalées ne sont pas considérées comme réussies.",
    "it": "Eventi di processo osservati ed errori rilevati. I passaggi DNS, di rete e di autenticazione non segnalati non vengono considerati riusciti.",
    "ja": "観測されたプロセスイベントと検出されたエラー。報告されていない DNS、ネットワーク、認証の各ステップを成功とはみなしません。",
    "pt": "Eventos de processo observados e erros detetados. Os passos de DNS, rede e autenticação não comunicados não são considerados bem-sucedidos.",
    "ru": "Наблюдаемые события процесса и обнаруженные ошибки. Этапы DNS, сети и аутентификации, о которых нет сведений, не считаются успешными.",
    "zh": "已观察到的进程事件和检测到的错误。未报告的 DNS、网络和认证步骤不会被推断为成功。"
  },
