  "Highlighted text can always be pasted with a middle-click. Hold Shift to select or open the menu inside tmux, vim and other mouse-aware apps.": {
    "en": "Highlighted text can always be pasted with a middle-click. Hold Shift to select or open the menu inside tmux, vim and other mouse-aware apps.",
    "de": "Markierter Text kann immer per Mittelklick eingefügt werden. Halten Sie Umschalt gedrückt, um in tmux, vim und anderen mausfähigen Programmen zu markieren oder das Menü zu öffnen.",
    "es": "El texto resaltado siempre se puede pegar con un clic central. Mantenga pulsada Mayús para seleccionar o abrir el menú dentro de tmux, vim y otras aplicaciones que usan el ratón.",
    "fr": "Le texte surligné peut toujours être collé d’un clic du milieu. Maintenez Maj pour sélectionner ou ouvrir le menu dans tmux, vim et les autres applications qui utilisent la souris.",
    "it": "Il testo evidenziato si può sempre incollare con un clic centrale. Tieni premuto Maiusc per selezionare o aprire il menu in tmux, vim e altre app che usano il mouse.",
    "ja": "ハイライトしたテキストはいつでも中クリックで貼り付けられます。tmux や vim などマウス対応アプリ内では Shift を押しながら選択またはメニューを開きます。",
    "pt": "O texto destacado pode sempre ser colado com o clique do meio. Mantenha Shift premido para selecionar ou abrir o menu no tmux, vim e outras aplicações que usam o rato.",
    "ru": "Выделенный текст всегда можно вставить средней кнопкой мыши. Удерживайте Shift, чтобы выделять или открыть меню в tmux, vim и других приложениях с поддержкой мыши.",
    "zh": "高亮的文本始终可以用鼠标中键粘贴。在 tmux、vim 等支持鼠标的应用中，按住 Shift 即可选择文本或打开菜单。"
  },
