  "A JSON array or an object with a profiles array. Sync shares connection names, hosts, ports, users, groups and tags; startup commands, keys, jump hosts and forwarding stay as set on this computer.": {
    "en": "A JSON array or an object with a profiles array. Sync shares connection names, hosts, ports, users, groups and tags; startup commands, keys, jump hosts and forwarding stay as set on this computer.",
    "de": "Ein JSON-Array oder ein Objekt mit einem profiles-Array. Die Synchronisierung teilt Verbindungsnamen, Hosts, Ports, Benutzer, Gruppen und Tags; Startbefehle, Schlüssel, Jump-Hosts und Weiterleitungen bleiben wie auf diesem Computer eingestellt.",
    "es": "Un array JSON o un objeto con un array profiles. La sincronización comparte nombres de conexión, hosts, puertos, usuarios, grupos y etiquetas; los comandos de inicio, claves, hosts de salto y reenvíos se mantienen como en este equipo.",
    "fr": "Un tableau JSON ou un objet avec un tableau profiles. La synchronisation partage les noms de connexion, hôtes, ports, utilisateurs, groupes et étiquettes ; les commandes de démarrage, clés, hôtes de rebond et redirections restent tels que définis sur cet ordinateur.",
    "it": "Un array JSON o un oggetto con un array profiles. La sincronizzazione condivide nomi di connessione, host, porte, utenti, gruppi e tag; comandi di avvio, chiavi, host di salto e inoltri restano come impostati su questo computer.",
    "ja": "JSON 配列、または profiles 配列を持つオブジェクト。同期で共有されるのは接続名、ホスト、ポート、ユーザー、グループ、タグです。起動コマンド、鍵、ジャンプホスト、転送はこのコンピューターの設定のままです。",
    "pt": "Um array JSON ou um objeto com um array profiles. A sincronização partilha nomes de ligações, hosts, portas, utilizadores, grupos e etiquetas; comandos de arranque, chaves, hosts de salto e reencaminhamentos ficam como definidos neste computador.",
    "ru": "Массив JSON или объект с массивом profiles. Синхронизируются имена подключений, хосты, порты, пользователи, группы и теги; команды запуска, ключи, промежуточные хосты и перенаправление остаются такими, как настроены на этом компьютере.",
    "zh": "JSON 数组，或包含 profiles 数组的对象。同步会共享连接名称、主机、端口、用户、分组和标签；启动命令、密钥、跳板机和转发保持本机上的设置。"
  },
  "This backup contains startup commands that run when you connect. Restore it only if you trust where it came from:": {
    "en": "This backup contains startup commands that run when you connect. Restore it only if you trust where it came from:",
    "de": "Diese Sicherung enthält Startbefehle, die beim Verbinden ausgeführt werden. Stellen Sie sie nur wieder her, wenn Sie der Quelle vertrauen:",
    "es": "Esta copia contiene comandos de inicio que se ejecutan al conectar. Restáurela solo si confía en su origen:",
    "fr": "Cette sauvegarde contient des commandes de démarrage exécutées à la connexion. Ne la restaurez que si vous faites confiance à sa provenance :",
    "it": "Questo backup contiene comandi di avvio eseguiti alla connessione. Ripristinalo solo se ti fidi della provenienza:",
    "ja": "このバックアップには接続時に実行される起動コマンドが含まれています。入手元を信頼できる場合にのみ復元してください:",
    "pt": "Esta cópia contém comandos de arranque que são executados ao ligar. Restaure-a apenas se confiar na origem:",
    "ru": "В этой резервной копии есть команды запуска, выполняемые при подключении. Восстанавливайте её, только если доверяете источнику:",
    "zh": "此备份包含连接时运行的启动命令。仅在信任其来源时才恢复："
  },
